friend constexpr auto operator<=>(const /*iterator*/ &x, const /*iterator*/ &y)

    requires ranges::random_access_range<Base> &&

    std::three_way_comparable</*ziperator*/<Const>>;

intro:
Compares the underlying iterators. Let inner_ denote the underlying iterator.

Equivalent to:

1) return x.inner_ == y.inner_;

2) return x.inner_ <=> y.inner_;

These functions are not visible to ordinary unqualified or qualified lookup, and can only be found by argument-dependent lookup when std::ranges::zip_transform_view::iterator<Const> is an associated class of the arguments.

The <, <=, >, >=, and != operators are synthesized from operator<=> and operator== respectively.

examples.code:
#include <ranges>
#include <iterator>
#include <functional>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    int values[]{3, 5, 7, 9};
    [[maybe_unused]] int nested[][2]{{1, 2}, {3, 4}};
    [[maybe_unused]] std::pair<int, int> pairs[]{{1, 10}, {2, 20}, {3, 30}};
    auto view = std::ranges::zip_transform_view{
        [](int a, int b) { return a + b; }, values, values};
    auto position = view.begin();
    auto finish = view.end();
    assert(position != finish);
    (void)*position;
    auto copy = position;
    assert(copy == position);
    ++position;
    assert(position != copy);
    --position;
    assert(position == copy);
    position += 1;
    position -= 1;
    assert(position - copy == 0);
    assert(copy + 1 > copy);
    assert(1 + copy == copy + 1);
    (void)position[0];
    (void)std::ranges::iter_move(copy);

    assert(std::ranges::distance(view) > 0);
    std::cout << "Checks passed\n";
}
